const input = $input.first().json;
const execution = input.execution ?? {};
const trigger = input.trigger ?? {};
const error = execution.error ?? trigger.error ?? {};
const executionId = String(execution.id ?? 'trigger');

return [{
  json: {
    logId: `error-${Date.now()}-${executionId}`,
    log: {
      occurredAt: $now.toISO(),
      workflowId: input.workflow?.id ?? null,
      workflowName: input.workflow?.name ?? null,
      executionId: execution.id ?? null,
      executionUrl: execution.url ?? null,
      mode: execution.mode ?? trigger.mode ?? null,
      lastNodeExecuted: execution.lastNodeExecuted ?? error.node?.name ?? null,
      message: error.message ?? 'Unknown workflow error',
    },
  },
}];

