const prepared = $('Code - Prepare Error Log').item.json;
const existingLogs = $input.first().json ?? {};
const logEntries = Object.entries(existingLogs)
  .filter(([, log]) => log && typeof log === 'object');

const deleteCount = Math.max(0, logEntries.length - 23);
const oldestEntries = logEntries
  .sort(sortByOccurredAt)
  .slice(0, deleteCount);

const firebaseUpdate = {
  [prepared.logId]: prepared.log,
};

oldestEntries.forEach(([logId]) => {
  firebaseUpdate[logId] = null;
});

return [{
  json: {
    ...prepared,
    firebaseUpdate,
  },
}];

/** Sorts Firebase logs from oldest to newest. */
function sortByOccurredAt([, first], [, second]) {
  return getTimestamp(first) - getTimestamp(second);
}

/** Returns a safe timestamp from one error log. */
function getTimestamp(log) {
  const timestamp = Date.parse(log.occurredAt ?? '');

  return Number.isNaN(timestamp) ? 0 : timestamp;
}
